import{_ as t,o as n,c as a,ag as o}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"Privacy","description":"What Mutelink sends outside your PC and stores locally, including recognition, translation, usage reports and feedback.","frontmatter":{"description":"What Mutelink sends outside your PC and stores locally, including recognition, translation, usage reports and feedback.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Privacy | Mutelink"}],["meta",{"property":"og:description","content":"What Mutelink sends outside your PC and stores locally, including recognition, translation, usage reports and feedback."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Privacy | Mutelink"}],["meta",{"name":"twitter:description","content":"What Mutelink sends outside your PC and stores locally, including recognition, translation, usage reports and feedback."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}]]},"headers":[],"relativePath":"en/about/privacy.md","filePath":"en/about/privacy.md"}'),r={name:"en/about/privacy.md"};function i(s,e,l,d,u,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="プライバシー" tabindex="-1">Privacy <a class="header-anchor" href="#プライバシー" aria-label="Permalink to &quot;Privacy {#プライバシー}&quot;">​</a></h1><p>This page explains the data Mutelink sends outside your PC.</p><h2 id="外部に送られるデータ" tabindex="-1">Data sent externally <a class="header-anchor" href="#外部に送られるデータ" aria-label="Permalink to &quot;Data sent externally {#外部に送られるデータ}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When</th><th>Data</th><th>Destination</th></tr></thead><tbody><tr><td>Cloud speech recognition</td><td>Microphone audio</td><td>Microsoft or Google</td></tr><tr><td>Azure Translator</td><td>Text to translate</td><td>Microsoft (your own key)</td></tr><tr><td>Google for incoming speech</td><td>Other people’s audio</td><td>Google</td></tr><tr><td>Sending incoming speech to the chatbox</td><td>Others’ words and translations</td><td>VRChat (visible to everyone in the instance)</td></tr><tr><td>Opt-in usage reporting</td><td>Anonymous usage data (below)</td><td>Developer’s Cloudflare server</td></tr><tr><td>Sending feedback</td><td>Your message and selected attachments (below)</td><td>Developer’s Cloudflare server and Discord</td></tr><tr><td>Downloads and update checks</td><td>Information needed for the connection only</td><td>Respective download providers</td></tr></tbody></table><p>The following run entirely on your PC and do not send data externally.</p><ul><li>Local recognition (Parakeet, Haas-ja, Qwen3-ASR, Whisper turbo)</li><li>Speech synthesis (VOICEVOX, Irodori-TTS, Qwen3-TTS)</li><li>Local translation (PLaMo, TranslateGemma)</li><li>VR keyboard kana-to-kanji and pinyin conversion</li></ul><p>With local incoming-speech recognition, others’ audio stays on your PC and is discarded immediately after recognition without being saved. Selecting Google sends their audio to Google. Use this considerately, for example by informing others.</p><p>VR panels for incoming speech and your chatbox are visible only to you. Streaming software that captures your VR view may also capture those panels.</p><h2 id="利用状況の送信" tabindex="-1">Usage reporting <a class="header-anchor" href="#利用状況の送信" aria-label="Permalink to &quot;Usage reporting {#利用状況の送信}&quot;">​</a></h2><p>To improve Mutelink, anonymous usage data is sent once a month <strong>only with your permission</strong>. Quick Setup asks at the end. Without permission, nothing is sent. Change your choice and preview the next report in Settings &gt; Other &gt; About.</p><ul><li><strong>Included</strong>: app version; OS, CPU, GPU and RAM; counts of launches, VR launches, recognition/synthesis/translation by engine, synthesis/translation errors, VR input actions and chatbox sends; settings such as per-language engines, translation priority, input method, usage choices and whether button layouts were customized; enabled paid features.</li><li><strong>Not included</strong>: speech content, recognized or typed text, voice audio, suffix text, templates, excluded words, history, device names, API keys, registered voice names, real names or contact details.</li><li><strong>Destination</strong>: a Cloudflare server operated by the developer. IP addresses are not stored.</li><li><strong>Purpose</strong>: understand feature usage and PC configurations to prioritize improvements.</li><li><strong>Anonymous ID</strong>: a random identifier created by the app, not linked to a person. Regenerate it in settings at any time.</li></ul><h2 id="不具合・要望の送信" tabindex="-1">Feedback reports <a class="header-anchor" href="#不具合・要望の送信" aria-label="Permalink to &quot;Feedback reports {#不具合・要望の送信}&quot;">​</a></h2><p>Send anonymous feedback from Settings &gt; Other &gt; About &gt; Send feedback. It is sent <strong>only when you press the send button</strong>, after you can review exactly what will be sent.</p><ul><li><strong>Always included</strong>: category (bug, request or other) and your message. Contact details are optional if you want a reply.</li><li><strong>Only if selected</strong>: app version and PC details (OS, CPU, RAM, GPU, VRAM), logs and one image. Logs and images are off by default.</li><li><strong>Logs exclude</strong>: lines containing speech or typed text are removed before sending. Usernames in file paths are masked.</li><li><strong>Images</strong>: anything visible, including notifications, names and filenames, is captured as-is. Images are delivered to the developer’s Discord, not saved on the server.</li><li><strong>Handling</strong>: IP addresses are not stored and reports are not linked to usage telemetry. Do not include personal information such as your name or address.</li></ul><h2 id="pcの中に保存されるデータ" tabindex="-1">Data stored on your PC <a class="header-anchor" href="#pcの中に保存されるデータ" aria-label="Permalink to &quot;Data stored on your PC {#pcの中に保存されるデータ}&quot;">​</a></h2><p>Downloaded models and characters, registered voice features (not the original recording), VR background images, license files, settings and translation character-count records are stored locally.</p><p>Fresh installations store data under <code>%LOCALAPPDATA%\\com.utyujinn.mutelink</code>. With upgrades from older versions, some data may remain in the installation folder.</p><p>Your Azure Translator key is saved only in settings on this PC.</p>',18)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
